ALTER TABLE "notification_attempts" DROP CONSTRAINT "notification_attempts_locale";--> statement-breakpoint
ALTER TABLE "notification_attempts" DROP CONSTRAINT "notification_attempts_phone";--> statement-breakpoint
ALTER TABLE "notification_attempts" ADD CONSTRAINT "notification_attempts_locale" CHECK (("notification_attempts"."locale" IS NOT NULL AND "notification_attempts"."locale" IN ('ar','en')) OR ("notification_attempts"."locale" IS NULL AND "notification_attempts"."status" = 'FAILED' AND "notification_attempts"."failure_code" IS NOT NULL AND "notification_attempts"."failure_code" IN ('LOCALE_MISSING','LOCALE_UNSUPPORTED')));--> statement-breakpoint
ALTER TABLE "notification_attempts" ADD CONSTRAINT "notification_attempts_phone" CHECK (("notification_attempts"."status" NOT IN ('SENT','FAILED','EXPIRED','SUPPRESSED') OR "notification_attempts"."recipient_phone" IS NULL) AND ("notification_attempts"."status" <> 'PENDING' OR "notification_attempts"."recipient_phone" IS NOT NULL) AND ("notification_attempts"."recipient_phone" IS NULL OR "notification_attempts"."recipient_phone" ~ '^[+][1-9][0-9]{7,14}$'));